window.AUTH=window.AUTH||{};window.AUTH["17-1107"]={"d":"17-1107","id":"2018/17-1107","n":"Carpenter v. Murphy","briefs":[{"k":"petitioner","label":"Brief of petitioner Mike Carpenter, Interim Warden","date":"2018-07-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1107/55210/20180723232225994_17-1107ts.pdf","side":"pet","n":60},{"k":"united-states","label":"Brief amicus curiae of United States of America","date":"2018-07-30","url":"https://www.supremecourt.gov/DocketPDF/17/17-1107/55946/20180730184937862_17-1107tsacUnitedStates.pdf","side":"us","n":54},{"k":"respondent","label":"Brief of respondent Patrick Dwayne Murphy","date":"2018-09-19","url":"https://www.supremecourt.gov/DocketPDF/17/17-1107/64320/20180919163608412_17-1107%20Brief%20of%20Respondent.pdf","side":"res","n":70},{"k":"reply","label":"Reply of petitioner Mike Carpenter, Interim Warden","date":"2018-10-19","url":"https://www.supremecourt.gov/DocketPDF/17/17-1107/67557/20181019174435281_17-1107rb%2010-19-18.pdf","side":"pet","n":21}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US2PP_web.pdf#page=536","tr":true,"items":[{"t":"case","label":"Adoptive Couple v. Baby Girl","cite":"570 U.S. 637","y":2013,"id":"2012/12-399","sc":1,"sum":"The Court held that a non-custodial parent cannot stop an adoption made lawfully by a non-Indian parent by invoking the ICWA.","sumSrc":"Oyez","by":{"0":"56"}},{"t":"case","label":"Bailey v. United States","cite":"104 P. 917","y":1909,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./104/917/","by":{"0":"40"}},{"t":"case","label":"Barnett v. Way","cite":"119 P. 418","y":1911,"court":"Okla.","url":"https://www.courtlistener.com/c/P./119/418/","by":{"0":"7"}},{"t":"case","label":"Bartlett v. United States","cite":"203 F. 410","y":1913,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./203/410/","by":{"0":"54"}},{"t":"case","label":"Board of Cty. Comm’rs v. Seber","cite":"318 U.S. 705","y":1943,"id":"scdb/1942-098","sc":1,"sum":"1. Lands theretofore purchased with restricted funds derived from an oil and gas lease of restricted allotted lands of a Creek Indian, held, under the Act of June 20,1936, immune from tax by Oklahoma for the year 1937, where, on the assessment date, the Indian owned a life estate in such lands subject to restrictions against alienation except with the approval of the Secretary of the Interior.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54"}},{"t":"case","label":"Bigfeather v. State","cite":"123 P. 1026","y":1912,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./123/1026/","by":{"0":"42"}},{"t":"case","label":"Buster v. Wright","cite":"135 F. 947","y":1905,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./135/947/","ar":1,"by":{"0":"35","2":"11, 34","3":"5"}},{"t":"case","label":"Coyle v. Smith","cite":"221 U.S. 559","y":1911,"id":"1900-1940/221us559","sc":1,"sum":"This was congressional overreaching. States are on an equal footing to determine their own location for the seat of government.","sumSrc":"Oyez","by":{"0":"22","2":"13, 38","3":"9"}},{"t":"case","label":"DeCoteau v. District Cty. Ct.","cite":"420 U.S. 425","y":1975,"id":"1974/73-1148","sc":1,"sum":"The Lake Traverse Indian Reservation in South Dakota, created by an 1867 treaty, held terminated and returned to the public domain by an 1891 Act which, in ratification of a previously negotiated 1889 Agreement between the affected Indian tribe and the United States, not only opened all unallotted lands to settlement but also appropriated and vested in the tribe a sum certain per acre in payment for the express …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 45, 52","1":"7","2":"27, 37"}},{"t":"case","label":"Grayson v. Harris","cite":"267 U.S. 352","y":1927,"id":"scdb/1924-105","sc":1,"sum":"1. Judgment held reviewable by certiorari and not by writ of error. P. 353. <..","sumSrc":"Headnote (U.S. Reports)","by":{"0":"54","2":"53"}},{"t":"case","label":"Hagen v. Utah","cite":"510 U.S. 399","y":1994,"id":"1993/92-6281","sc":1,"sum":"Petitioner, an Indian, was charged in Utah state court with distribution of a controlled substance in the town of Myton, which lies within the original boundaries of the Uintah Indian Reservation on land that was opened to non-Indian settlement in 1905. The trial court rejected petitioner's claim that it lacked. jurisdiction over him because he was an Indian and the crime had been committed in \"Indian country,\" see …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 24, 43, 49, 50, 52","1":"6, 11, 18, 23","2":"11, 13, 14","3":"15"}},{"t":"case","label":"Haikey v. State","cite":"105 P. 313","y":1909,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./105/313/","by":{"0":"39, 40"}},{"t":"case","label":"Harjo v. Kleppe","cite":"420 F. Supp. 1110","y":1976,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./420/1110/","sum":"Describing Congress’s “statutory dismemberment” of the Creek Nation.","sumSrc":"brief:0","by":{"0":"28, 36","1":"27"}},{"t":"case","label":"Heckman v. United States","cite":"224 U.S. 413","y":1912,"id":"scdb/1911-217","sc":1,"sum":"The United States has capacity to maintain a suit to set aside conveyances made by allottee Indians of allotted lands within the statutory period of restriction; and this suit brought against numerous defendants, all of whom were grantees of allottees of the same tribe, is properly maintainable in equity; the return of the consideration to the grantee is not essential; there is no defect of parties because the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"9"}},{"t":"case","label":"Hendrix v. United States","cite":"219 U.S. 79","y":1911,"id":"scdb/1910-050","sc":1,"ar":1,"sum":"The United States court at a particular place named is a sufficient designation of the only court of the United States held at that place, which has jurisdiction of the case; and an order transmitting a case under the act.of June 28, 1898, c. 517, 30 Stat. 511, to the United States court at Paris, Texas, is sufficient to transfer the case to the District Court of the United States for the Eastern District of Texas, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42","1":"30","2":"47","3":"11"}},{"t":"case","label":"Jefferson v. Fink","cite":"247 U.S. 288","y":1918,"id":"scdb/1917-139","sc":1,"sum":"The policy and legislation of Congress respecting the descent of Indian allotments, particularly in the Five Civilized Tribes, reviewed.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"8, 27, 29","1":"17"}},{"t":"case","label":"Jones v. State","cite":"107 P. 738","y":1910,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./107/738/","by":{"0":"39"}},{"t":"case","label":"Keys v. United States","cite":"103 P. 874","y":1909,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./103/874/","by":{"0":"40"}},{"t":"case","label":"Magnan v. Trammell","cite":"719 F.3d 1159","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/719/1159/","by":{"0":"45"}},{"t":"case","label":"Marlin v. Lewallen","cite":"276 U.S. 58","y":1928,"id":"scdb/1927-089","sc":1,"sum":"1. The surviving husband of a woman of the Creek blood and tribe, whether himself of that blood or not, has no estate of curtesy in land allotted and patented to her in the distribution of the tribal property under the original and supplemental Creek Agreements, Acts of March 1, 1901, and June 30, 1902, and of which she died seized, intestate and leaving issue. Pp. 59, 68.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"8, 9, 10, 11, 28, 38","1":"8, 13, 15"}},{"t":"case","label":"Mattz v. Arnett","cite":"412 U.S. 481","y":1973,"id":"1972/71-1182","sc":1,"sum":"The Klamath River Reservation was not terminated by the Act of June 17, 1892, and the land within the reservation boundaries is still Indian country, within theoneaning of 18 U. S. C. § 1151.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 46, 47","1":"17","2":"20, 23-24, 25, 31, 40, 53"}},{"t":"case","label":"McDougal v. McKay","cite":"237 U.S. 372","y":1915,"id":"scdb/1914-092","sc":1,"sum":"In construing an Act of Congress, its known purpose must be effectuated as nearly as may be.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"8, 19, 28, 55","1":"15","2":"53"}},{"t":"case","label":"Oklahoma Tax Comm’n v. United States","cite":"319 U.S. 598","y":1943,"id":"scdb/1942-059","sc":1,"by":{"0":"54, 55","1":"21"}},{"t":"case","label":"Osage Nation v. Irby","cite":"597 F.3d 1117","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/597/1117/","by":{"0":"54"}},{"t":"case","label":"Phillips v. United States","cite":"103 P. 861","y":1909,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./103/861/","by":{"0":"40"}},{"t":"case","label":"Plains Commerce Bank v. Long Family Land & Cattle Co.","cite":"554 U.S. 316","y":2008,"id":"2007/07-411","sc":1,"ar":2,"sum":"On this issue, the Court held unanimously that tribal courts do not have jurisdiction to hear disputes concerning non- Indian banks' sales of their own lands. Writing for the Court, Chief Justice John G. Roberts stated that although tribal courts have jurisdiction to regulate conduct occurring on tribal lands, that jurisdiction is lost once title to the land passes into the hands of non-Indians.","sumSrc":"Oyez","by":{"0":"29","2":"56"}},{"t":"case","label":"Price v. United States","cite":"101 P. 1036","y":1909,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./101/1036/","by":{"0":"40"}},{"t":"case","label":"Ramah Navajo Sch. Bd., Inc. v. Bureau of Revenue of N.M.","cite":"458 U.S. 832","y":1982,"id":"1981/80-2162","sc":1,"sum":"Federal law pre-empts New Mexico's tax imposed on the gross receipts that appellant non-Indian construction company received from appellant triba school board for the construction of a school for Indian children on the reservation. White Mountain Apache Tribe v. Bracker, 448 U. S. 136, controlling.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Rollen v. State","cite":"125 P. 1087","y":1912,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./125/1087/","by":{"0":"42","1":"30"}},{"t":"case","label":"Seymour v. Superintendent of Wash. State Penitentiary","cite":"368 U.S. 351","y":1962,"id":"1961/62","sc":1,"sum":"The Colville Indian Reservation is still in existence; the land upon which the offense is alleged to have occurred is within the limits of that Reservation; the state courts had no jurisdiction to try petitioner for that offense; and the judgment denying habeas corpus is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 46","1":"17","2":"24, 31, 37","3":"16"}},{"t":"case","label":"Sharp v. United States","cite":"118 P. 675","y":1911,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./118/675/","by":{"0":"40"}},{"t":"case","label":"Shulthis v. McDougal","cite":"170 F. 529","y":1909,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./170/529/","by":{"0":"55"}},{"t":"case","label":"Sizemore v. Brady","cite":"235 U.S. 441","y":1914,"id":"scdb/1914-037","sc":1,"sum":"The Original Creek Agreement of March 1, 1901, was not a grant in prossenti which invested the then living members.of the tribe and their heirs with absolute rights that could not be recalled or impaired by Congress without violating the due process clause of the Fifth Amendment,","sumSrc":"Headnote (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Solem v. Bartlett","cite":"465 U.S. 463","y":1984,"id":"1983/82-1253","sc":1,"ar":16,"sum":"The Act did not diminish the reservation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim","3":"1, 7, 14"}},{"t":"case","label":"South Dakota v. Yankton Sioux Tribe","cite":"522 U.S. 329","y":1998,"id":"1997/96-1581","sc":1,"op":1,"ar":1,"sum":"The Court held that the 1894 statute's operative language and the circumstances surrounding its passage demonstrate that Congress intended to diminish the Yankton Reservation and as a result the unallotted lands ceded did not retain reservation status.","sumSrc":"Oyez","by":{"0":"24, 47, 49, 51, 52","1":"6, 22, 23, 25","2":"23, 27, 37, 39, 50"}},{"t":"case","label":"Spalding v. Chandler","cite":"160 U.S. 394","y":1896,"id":"scdb/1895-085","sc":1,"sum":"The Indian reservation at Sault Ste. Marie, under the treaty of June 26, 1820, with the CJiippewas, continued until extinguished by the treaty of August 2, 1855; and upon the extinguishment of the Indian title at that time the land.included in the reservation was made, by § 10 of the act of September 4,1841, not subject to preemption.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"State v. Klindt","cite":"782 P.2d 401","y":1989,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/782/401/","sum":"Holding that restricted allotments are “Indian country” under 18 U.S.C. § 1151(c).","sumSrc":"brief:0","by":{"0":"45","1":"32","2":"15, 47","3":"8, 12"}},{"t":"case","label":"Stephens v. Cherokee Nation","cite":"174 U.S. 445","y":1899,"id":"scdb/1898-156","sc":1,"sum":"Congress may provide for a review of the action of commissioners and boards created by it and exercising only quasi judicial powers, by a transfer of their proceedings and decisions to judicial tribunals for examination and determination de novo.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"8","1":"9"}},{"t":"case","label":"Tiger v. W. Inv. Co.","cite":"221 U.S. 286","y":1911,"id":"scdb/1910-140","sc":1,"sum":"The obvious purpose of § 8 of the act of May 27,1908, c. 199, 35 Stat. 312, was to continue supervision over the right of full-blood Indians i to dispose of lands by will, and to require conveyances of interests of full-blood Indians in inherited lands to be approved by a compe- tent court.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"9, 28","3":"3"}},{"t":"case","label":"U.S. Express Co. v. Friedman","cite":"191 F. 673","y":1911,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./191/673/","sum":"Rejecting argument that former Indian Territory land “ceased to be Indian country upon” statehood.","sumSrc":"brief:2","by":{"0":"45","2":"52","3":"8, 19"}},{"t":"case","label":"United States v. Adair","cite":"913 F. Supp. 1503","y":1995,"court":"E.D. Okla.","url":"https://www.courtlistener.com/c/F.%20Supp./913/1503/","sum":"Concluding that land was not a dependent Indian community and therefore not Indian country.","sumSrc":"brief:0","by":{"0":"45"}},{"t":"case","label":"United States v. Allen","cite":"171 F. 907","y":1909,"court":"E.D. Okla.","url":"https://www.courtlistener.com/c/F./171/907/","by":{"0":"38"}},{"t":"case","label":"United States v. Celestine","cite":"215 U.S. 278","y":1909,"id":"scdb/1909-032","sc":1,"sum":"Although an Indian may be made a citizen of the United States.ándof the State in which the reservation for his tribe is. located, the United States may still retain jurisdiction over him for offenses committed within the limits of the reservation; and so held as to a crime committed by an Indian against another Indian on the Tulalip Indian Reservation in Washington, notwithstanding the Indians had received …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24","2":"22, 31, 35"}},{"t":"case","label":"United States v. Creek Nation","cite":"295 U.S. 103","y":1935,"id":"scdb/1934-113","sc":1,"sum":"Counsel for Parties. (1) That the claim of the Creek Tribe for compensation was a claim \"arising under or growing out of\" a \"treaty or agreement\" between the United States and that Tribe, or \"arising under or growing out of\" an \"Act of Congress in relation to Indian Affairs,\"/-within the meaning of the Act of May 24, 1924, conferring jurisdiction on the Court of Claims to adjudicate. P. 108. (2) The lands were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 34"}},{"t":"case","label":"United States v. Okla. Gas & Elec. Co.","cite":"318 U.S. 206","y":1943,"id":"scdb/1942-093","sc":1,"sum":"1. A permit granted by the Secretary of the Interior under § 4 of the Act of March 3, 1901, to the State of Oklahoma to open and establish a public highway over Indian allotted lands, is to be construed, in the absence of any governing administrative ruling, statute, or Congressional policy to the contrary, as authorizing the State to license the erection and maintenance of a rural electric service line, a proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"United States v. Roberts","cite":"185 F.3d 1125","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/185/1125/","by":{"0":"45"}},{"t":"case","label":"United States v. Sands","cite":"968 F.2d 1058","y":1992,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/968/1058/","by":{"0":"45","1":"32","3":"8, 12"}},{"t":"case","label":"Washington v. Miller","cite":"235 U.S. 422","y":1914,"id":"scdb/1914-047","sc":1,"sum":"Under the original Creek Agreement of March 1, 1901, controlling effect was given to the Creek tribal laws of descent, and distribution rather than to the laws of Arkansas upon that subject put in force in tbe Indian Territory, and the provisions giving such effect to the tribal laws embraced allotments to living citizens as well as allotments on behalf of deceased citizens.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"10, 29, 38, 54","1":"21","2":"53"}},{"t":"case","label":"Williams v. Lee","cite":"358 U.S. 217","y":1959,"id":"1958/39","sc":1,"sum":"The Court held that the jurisdiction of state courts does not extend to Indian reservations unless Congress specifically permits.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Wilson v. United States","cite":"111 P. 659","y":1910,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./111/659/","by":{"0":"40"}},{"t":"case","label":"Woodward v. de Graffenried","cite":"238 U.S. 284","y":1915,"id":"scdb/1914-169","sc":1,"sum":"In an action to determine by what law the beneficiaries of a Creek allotment are to be determined where the allotment was selected by a Creek citizen and made by the Dawes Commission under § 11 of the Curtis Act of June 28, 1898, followed first by the death of the allottee after.receiving the allotment and prior to the Original Creek Agreement and then by action of the Commission, after ratification of that …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"8, 25, 26, 27, 54","1":"8, 10, 11, 12, 18, 21","2":"6, 7, 8, 41, 53"}},{"t":"usc","label":"12 U.S.C. § 4702","url":"https://www.law.cornell.edu/uscode/text/12/4702","subs":["(11)"],"stext":{"head":"§4702. Definitions","paras":[[0,"For purposes of this subchapter, the following definitions shall apply:"],[0,"(1) Administrator"],[1,"The term \"Administrator\" means the Administrator of the Fund appointed under section 4703(b) of this title."],[0,"(2) Appropriate Federal banking agency"],[1,"The term \"appropriate Federal banking agency\" has the same meaning as in section 1813 of this title, and also includes the National Credit Union Administration Board with respect to insured credit unions."],[0,"(3) Affiliate"],[1,"The term \"affiliate\" has the same meaning as in section 1841(k) of this title."],[0,"(4) Board"],[1,"The term \"Board\" means the Community Development Advisory Board established under section 4703(d) of this title."],[0,"(5) Community development financial institution"],[0,"(A) In general"],[2,"The term \"community development financial institution\" means a person (other than an individual) that—"],[3,"(i) has a primary mission of promoting community development;"],[3,"(ii) serves an investment area or targeted population;"],[3,"(iii) provides development services in conjunction with equity investments or loans, directly or through a subsidiary or affiliate;"],[3,"(iv) maintains, through representation on its governing board or otherwise, accountability to residents of its investment area or targeted population; and"],[3,"(v) is not an agency or instrumentality of the United States, or of any State or political subdivision of a State."],[0,"(B) Conditions for qualification of holding companies"],[0,"(i) Consolidated treatment"],[3,"A depository institution holding company may qualify as a community development financial institution only if the holding company and the subsidiaries and affiliates of the holding company collectively satisfy the requirements of subparagraph (A)."],[0,"(ii) Exclusion of subsidiary or affiliate for failure to meet consolidated treatment rule"],[3,"No subsidiary or affiliate of a depository institution holding company may qualify as a community development financial institution if the holding company and the subsidiaries and affiliates of the holding company do not collectively meet the requirements of subparagraph (A)."],[0,"(C) Conditions for subsidiaries"],[2,"No subsidiary of an insured depository institution may qualify as a community development financial institution if the insured depository institution and its subsidiaries do not collectively meet the requirements of subparagraph (A)."],[0,"(6) Community partner"],[1,"The term \"community partner\" means a person (other than an individual) that provides loans, equity investments, or development services, including a depository institution holding company, an insured depository institution, an insured credit union, a nonprofit organization, a State or local government agency, a quasi-governmental entity, and an investment company authorized to operate pursuant to the Small Business Investment Act of 1958 [15 U.S.C. 661 et seq.]."],[0,"(7) Community partnership"],[1,"The term \"community partnership\" means an agreement between a community development financial institution and a community partner to provide development services, loans, or equity investments, to an investment area or targeted population."],[0,"(8) Depository institution holding company"],[1,"The term \"depository institution holding company\" has the same meaning as in section 1813 of this title."],[0,"(9) Development services"],[1,"The term \"development services\" means activities that promote community development and are integral to lending or investment activities, including—"],[2,"(A) business planning;"],[2,"(B) financial and credit counseling; and"],[2,"(C) marketing and management assistance."],[0,"(10) Fund"],[1,"The term \"Fund\" means the Community Development Financial Institutions Fund established under section 4703(a) of this title."],[0,"(11) Indian reservation"],[1,"The term \"Indian reservation\" has the same meaning as in section 1903(10) of title 25, and shall include land held by incorporated Native groups, regional corporations, and village corporations, as defined in or established pursuant to the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.], public domain Indian allotments, and former Indian reservations in the State of Oklahoma."],[0,"(12) Indian tribe"],[1,"The term \"Indian tribe\" means any Indian tribe, band, pueblo, nation, or other organized group or community, including any Alaska Native village or regional or village corporation, as defined in or established pursuant to the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.], which is recognized as eligible for the special programs and services provided by the United States to Indians because of their status as Indians."],[0,"(13) Insured community development financial institution"],[1,"The term \"insured community development financial institution\" means any community development financial institution that is an insured depository institution or an insured credit union."],[0,"(14) Insured credit union"],[1,"The term \"insured credit union\" has the same meaning as in section 1752(7) of this title."],[0,"(15) Insured depository institution"],[1,"The term \"insured depository institution\" has the same meaning as in section 1813 of this title."],[0,"(16) Investment area"],[1,"The term \"investment area\" means a geographic area (or areas) including an Indian reservation that—"],[2,"(A)(i) meets objective criteria of economic distress developed by the Fund, which may include the percentage of low-income families or the extent of poverty, the rate of unemployment or underemployment, rural population outmigration, lag in population growth, and extent of blight and disinvestment; and"],[2,"(ii) has significant unmet needs for loans or equity investments; or"],[2,"(B) encompasses or is located in an empowerment zone or enterprise community designated under section 1391 of title 26."],[0,"(17) Low-income"],[1,"The term \"low-income\" means having an income, adjusted for family size, of not more than—"],[2,"(A) for metropolitan areas, 80 percent of the area median income; and"],[2,"(B) for nonmetropolitan areas, the greater of—"],[3,"(i) 80 percent of the area median income; or"],[3,"(ii) 80 percent of the statewide nonmetropolitan area median income."],[0,"(18) State"],[1,"The term \"State\" has the same meaning as in section 1813 of this title."],[0,"(19) Subsidiary"],[1,"The term \"subsidiary\" has the same meaning as in section 1813 of this title, except that a community development financial institution that is a corporation shall not be considered to be a subsidiary of any insured depository institution or depository institution holding company that controls less than 25 percent of any class of the voting shares of such corporation, and does not otherwise control in any manner the election of a majority of the directors of the corporation."],[0,"(20) Targeted population"],[1,"The term \"targeted population\" means individuals, or an identifiable group of individuals, including an Indian tribe, who—"],[2,"(A) are low-income persons; or"],[2,"(B) otherwise lack adequate access to loans or equity investments."],[0,"(21) Training program"],[1,"The term \"training program\" means the training program operated by the Fund under section 4708 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/4702?type=usc&year=mostrecent&link-type=html"},"head":"§4702. Definitions","tname":"Banks and Banking","by":{"0":"55","1":"21"}},{"t":"usc","label":"16 U.S.C. § 1722","url":"https://www.law.cornell.edu/uscode/text/16/1722","subs":["(6)(C)"],"by":{"0":"55"}},{"t":"usc","label":"18 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/18/1151","subs":["(a)","(b)","(c)"],"stext":{"head":"§1151. Indian country defined","paras":[[0,"Except as otherwise provided in sections 1154 and 1156 of this title, the term \"Indian country\", as used in this chapter, means (a) all land within the limits of any Indian reservation under the jurisdiction of the United States Government, notwithstanding the issuance of any patent, and, including rights-of-way running through the reservation, (b) all dependent Indian communities within the borders of the United States whether within the original or subsequently acquired territory thereof, and whether within or without the limits of a state, and (c) all Indian allotments, the Indian titles to which have not been extinguished, including rights-of-way running through the same."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1151?type=usc&year=mostrecent&link-type=html"},"head":"§1151. Indian country defined","tname":"Crimes and Criminal Procedure","by":{"0":"1","1":"6, 31, 1, 2, 28, 31, 2, 2"}},{"t":"usc","label":"25 U.S.C. § 1452","url":"https://www.law.cornell.edu/uscode/text/25/1452","subs":["(d)"],"stext":{"head":"§1452. Definitions","paras":[[0,"For the purpose of this chapter, the term—"],[0,"(a) \"Secretary\" means the Secretary of the Interior."],[0,"(b) \"Indian\" means any person who is a member of any Indian tribe, band, group, pueblo, or community which is recognized by the Federal Government as eligible for services from the Bureau of Indian Affairs and any \"Native\" as defined in the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.]."],[0,"(c) \"Tribe\" means any Indian tribe, band, group, pueblo, or community, including Native villages and Native groups (including corporations organized by Kenai, Juneau, Sitka, and Kodiak) as defined in the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.], which is recognized by the Federal Government as eligible for services from the Bureau of Indian Affairs."],[0,"(d) \"Reservation\" includes Indian reservations, public domain Indian allotments, former Indian reservations in Oklahoma, and land held by incorporated Native groups, regional corporations, and village corporations under the provisions of the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.]."],[0,"(e) \"Economic enterprise\" means any Indian-owned (as defined by the Secretary of the Interior) commercial, industrial, or business activity established or organized for the purpose of profit: Provided, That such Indian ownership shall constitute not less than 51 per centum of the enterprise."],[0,"(f) \"Organization\", unless otherwise specified, shall be the governing body of any Indian tribe, as defined in subsection (c), or entity established or recognized by such governing body for the purpose of this chapter."],[0,"(g) \"Other organizations\" means any non-Indian individual, firm, corporation, partnership, or association."],[0,"(h) \"Surety\" has the same meaning as in section 694a of title 15."],[0,"(i) \"Surety Bond\" means a bid bond, payment bond, or performance bond as those terms are defined in section 694a of title 15."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1452?type=usc&year=mostrecent&link-type=html"},"head":"§1452. Definitions","tname":"Indians","by":{"0":"55","1":"21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 741","url":"https://www.law.cornell.edu/uscode/text/29/741","subs":["(d)"],"stext":{"head":"§741. Vocational rehabilitation services grants","paras":[[0,"(a) Governing bodies of Indian tribes; amount; non-Federal share"],[0,"The Commissioner, in accordance with the provisions of this part, may make grants to the governing bodies of Indian tribes located on Federal and State reservations (and consortia of such governing bodies) to pay 90 percent of the costs of vocational rehabilitation services for American Indians who are individuals with disabilities residing on or near such reservations (referred to in this section as \"eligible individuals\"), consistent with such eligible individuals' strengths, resources, priorities, concerns, abilities, capabilities, interests, and informed choice, so that such individuals may prepare for, and engage in, high-quality employment that will increase opportunities for economic self-sufficiency. The non-Federal share of such costs may be in cash or in kind, fairly valued, and the Commissioner may waive such non-Federal share requirement in order to carry out the purposes of this chapter."],[0,"(b) Application; effective period; continuation of programs and services; separate service delivery systems"],[0,"(1) No grant may be made under this part for any fiscal year unless an application therefor has been submitted to and approved by the Commissioner. The Commissioner may not approve an application unless the application—"],[1,"(A) is made at such time, in such manner, and contains such information as the Commissioner may require;"],[1,"(B) contains assurances that the rehabilitation services provided under this part to American Indians who are individuals with disabilities residing on or near a reservation in a State shall be, to the maximum extent feasible, comparable to rehabilitation services provided under this subchapter to other individuals with disabilities residing in the State and that, where appropriate, may include services traditionally used by Indian tribes;"],[1,"(C) contains assurances that the application was developed in consultation with the designated State unit of the State; and"],[1,"(D) contains assurances that—"],[2,"(i) all decisions affecting eligibility for vocational rehabilitation services, the nature and scope of available vocational rehabilitation services and the provision of such services will, consistent with this subchapter, be made by a representative of the tribal vocational rehabilitation program funded through the grant; and"],[2,"(ii) such decisions will not be delegated to another agency or individual."],[0,"(2) The provisions of sections 5305, 5306, 5307, and 5321(a) of title 25 shall be applicable to any application submitted under this part. For purposes of this paragraph, any reference in any such provision to the Secretary of Education or to the Secretary of the Interior shall be considered to be a reference to the Commissioner."],[0,"(3) Any application approved under this part shall be effective for not more than 60 months, except as determined otherwise by the Commissioner pursuant to prescribed regulations. The State shall continue to provide vocational rehabilitation services under its State plan to American Indians residing on or near a reservation whenever such State includes any such American Indians in its State population under section 730(a)(1) of this title."],[0,"(4) In making grants under this part, the Secretary shall give priority consideration to applications for the continuation of programs which have been funded under this part."],[0,"(5) Nothing in this section may be construed to authorize a separate service delivery system for Indian residents of a State who reside in non-reservation areas."],[0,"(c) Funds reserved for training and technical assistance"],[0,"(1) From the funds appropriated and made available to carry out this part for any fiscal year, beginning with fiscal year 2015, the Commissioner shall first reserve not less than 1.8 percent and not more than 2 percent of the funds to provide training and technical assistance to governing bodies described in subsection (a) for such fiscal year."],[0,"(2) From the funds reserved under paragraph (1), the Commissioner shall make grants to, or enter into contracts or other cooperative agreements with, entities that have experience in the operation of vocational rehabilitation services programs under this section to provide such training and technical assistance with respect to developing, conducting, administering, and evaluating such programs."],[0,"(3) The Commissioner shall conduct a survey of the governing bodies regarding training and technical assistance needs in order to determine funding priorities for such grants, contracts, or cooperative agreements."],[0,"(4) To be eligible to receive a grant or enter into a contract or cooperative agreement under this section, such an entity shall submit an application to the Commissioner at such time, in such manner, and containing a proposal to provide such training and technical assistance, and containing such additional information as the Commissioner may require. The Commissioner shall provide for peer review of applications by panels that include persons who are not government employees and who have experience in the operation of vocational rehabilitation services programs under this section."],[0,"(d) \"Reservation\" defined"],[0,"The term \"reservation\" includes Indian reservations, public domain Indian allotments, former Indian reservations in Oklahoma, and land held by incorporated Native groups, regional corporations, and village corporations under the provisions of the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/741?type=usc&year=mostrecent&link-type=html"},"head":"§741. Vocational rehabilitation services grants","tname":"Labor","by":{"0":"55","1":"21"}},{"t":"usc","label":"33 U.S.C. § 1377","url":"https://www.law.cornell.edu/uscode/text/33/1377","subs":["(c)(3)(B)","(c)"],"stext":{"head":"§1377. Indian tribes","paras":[[0,"(a) Policy"],[0,"Nothing in this section shall be construed to affect the application of section 1251(g) of this title, and all of the provisions of this section shall be carried out in accordance with the provisions of such section 1251(g) of this title. Indian tribes shall be treated as States for purposes of such section 1251(g) of this title."],[0,"(b) Assessment of sewage treatment needs; report"],[0,"The Administrator, in cooperation with the Director of the Indian Health Service, shall assess the need for sewage treatment works to serve Indian tribes, the degree to which such needs will be met through funds allotted to States under section 1285 of this title and priority lists under section 1296 of this title, and any obstacles which prevent such needs from being met. Not later than one year after February 4, 1987, the Administrator shall submit a report to Congress on the assessment under this subsection, along with recommendations specifying (1) how the Administrator intends to provide assistance to Indian tribes to develop waste treatment management plans and to construct treatment works under this chapter, and (2) methods by which the participation in and administration of programs under this chapter by Indian tribes can be maximized."],[0,"(c) Reservation of funds"],[0,"(1) Fiscal years 1987–2014"],[1,"The Administrator shall reserve each of fiscal years 1987 through 2014, before allotments to the States under section 1285(e) of this title, one-half of one percent of the sums appropriated under section 1287 of this title."],[0,"(2) Fiscal year 2015 and thereafter"],[1,"For fiscal year 2015 and each fiscal year thereafter, the Administrator shall reserve, before allotments to the States under section 1384(a) of this title, not less than 0.5 percent and not more than 2.0 percent of the funds made available to carry out subchapter VI."],[0,"(3) Use of funds"],[1,"Funds reserved under this subsection shall be available only for grants for projects and activities eligible for assistance under section 1383(c) of this title to serve—"],[2,"(A) Indian tribes (as defined in subsection (h));"],[2,"(B) former Indian reservations in Oklahoma (as determined by the Secretary of the Interior); and"],[2,"(C) Native villages (as defined in section 1602 of title 43)."],[0,"(d) Cooperative agreements"],[0,"In order to ensure the consistent implementation of the requirements of this chapter, an Indian tribe and the State or States in which the lands of such tribe are located may enter into a cooperative agreement, subject to the review and approval of the Administrator, to jointly plan and administer the requirements of this chapter."],[0,"(e) Treatment as States"],[0,"The Administrator is authorized to treat an Indian tribe as a State for purposes of subchapter II of this chapter and sections 1254, 1256, 1313, 1315, 1318, 1319, 1324, 1329, 1341, 1342, 1344, and 1346 of this title to the degree necessary to carry out the objectives of this section, but only if—"],[1,"(1) the Indian tribe has a governing body carrying out substantial governmental duties and powers;"],[1,"(2) the functions to be exercised by the Indian tribe pertain to the management and protection of water resources which are held by an Indian tribe, held by the United States in trust for Indians, held by a member of an Indian tribe if such property interest is subject to a trust restriction on alienation, or otherwise within the borders of an Indian reservation; and"],[1,"(3) the Indian tribe is reasonably expected to be capable, in the Administrator's judgment, of carrying out the functions to be exercised in a manner consistent with the terms and purposes of this chapter and of all applicable regulations."],[0,"Such treatment as a State may include the direct provision of funds reserved under subsection (c) to the governing bodies of Indian tribes, and the determination of priorities by Indian tribes, where not determined by the Administrator in cooperation with the Director of the Indian Health Service. The Administrator, in cooperation with the Director of the Indian Health Service, is authorized to make grants under subchapter II of this chapter in an amount not to exceed 100 percent of the cost of a project. Not later than 18 months after February 4, 1987, the Administrator shall, in consultation with Indian tribes, promulgate final regulations which specify how Indian tribes shall be treated as States for purposes of this chapter. The Administrator shall, in promulgating such regulations, consult affected States sharing common water bodies and provide a mechanism for the resolution of any unreasonable consequences that may arise as a result of differing water quality standards that may be set by States and Indian tribes located on common bodies of water. Such mechanism shall provide for explicit consideration of relevant factors including, but not limited to, the effects of differing water quality permit requirements on upstream and downstream dischargers, economic impacts, and present and historical uses and quality of the waters subject to such standards. Such mechanism should provide for the avoidance of such unreasonable consequences in a manner consistent with the objective of this chapter."],[0,"(f) Grants for nonpoint source programs"],[0,"The Administrator shall make grants to an Indian tribe under section 1329 of this title as though such tribe was a State. Not more than one-third of one percent of the amount appropriated for any fiscal year under section 1329 of this title may be used to make grants under this subsection. In addition to the requirements of section 1329 of this title, an Indian tribe shall be required to meet the requirements of paragraphs (1), (2), and (3) of subsection (d) 1 of this section in order to receive such a grant."],[0,"(g) Alaska Native organizations"],[0,"No provision of this chapter shall be construed to—"],[1,"(1) grant, enlarge, or diminish, or in any way affect the scope of the governmental authority, if any, of any Alaska Native organization, including any federally-recognized tribe, traditional Alaska Native council, or Native council organized pursuant to the Act of June 18, 1934 (48 Stat. 987), over lands or persons in Alaska;"],[1,"(2) create or validate any assertion by such organization or any form of governmental authority over lands or persons in Alaska; or"],[1,"(3) in any way affect any assertion that Indian country, as defined in section 1151 of title 18, exists or does not exist in Alaska."],[0,"(h) Definitions"],[0,"For purposes of this section, the term—"],[1,"(1) \"Federal Indian reservation\" means all land within the limits of any Indian reservation under the jurisdiction of the United States Government, notwithstanding the issuance of any patent, and including rights-of-way running through the reservation; and"],[1,"(2) \"Indian tribe\" means any Indian tribe, band, group, or community recognized by the Secretary of the Interior and exercising governmental authority over a Federal Indian reservation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1377?type=usc&year=mostrecent&link-type=html"},"head":"§1377. Indian tribes","tname":"Navigation and Navigable Waters","by":{"0":"55","1":"21"}},{"t":"usc","label":"42 U.S.C. § 2992c","url":"https://www.law.cornell.edu/uscode/text/42/2992c","subs":["(3)","(2)"],"stext":{"head":"§2992c. Definitions","paras":[[0,"As used in this subchapter, the term—"],[1,"(1) \"average\" means the aggregate number of hours of instruction through the use of a Native American language to all students enrolled in a native language immersion program during a school year divided by the total number of students enrolled in the immersion program;"],[1,"(2) \"financial assistance\" includes assistance advanced by grant, agreement, or contract, but does not include the procurement of plant or equipment, or goods or services;"],[1,"(3) \"Indian reservation or Alaska Native village\" includes the reservation of any federally or State recognized Indian Tribe, including any band, nation, pueblo, or rancheria, any former reservation in Oklahoma, and community under the jurisdiction of an Indian Tribe, including a band, nation, pueblo, or rancheria, with allotted lands or lands subject to a restriction against alienation imposed by the United States or a State, and any lands of or under the jurisdiction of an Alaska Native village or group, including any lands selected by Alaska Natives or Alaska Native organizations under the Alaska Native Claims Settlement Act [43 U.S.C. 1601 et seq.];"],[1,"(4) \"Native Hawaiian\" means any individual any of whose ancestors were natives of the area which consists of the Hawaiian Islands prior to 1778;"],[1,"(5) the term \"rule\" has the meaning given it in section 551(4) of title 5, as amended from time to time;"],[1,"(6) \"Secretary\" means the Secretary of Health and Human Services; and"],[1,"(7) the term \"Native American Pacific Islander\" means an individual who is indigenous to a United States territory or possession located in the Pacific Ocean, and includes such individual while residing in the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2992c?type=usc&year=mostrecent&link-type=html"},"head":"§2992c. Definitions","tname":"The Public Health and Welfare","by":{"0":"55","1":"21"}},{"t":"law","label":"Pub. L. No. 95-608","url":"https://www.govinfo.gov/link/statute/92/3069","by":{"0":"56"}},{"t":"case","label":"Atlantic & Pac. R.R. v. Mingus","cite":"165 U.S. 413","y":1897,"id":"scdb/1896-105","sc":1,"sum":"Congress did not intend by the statutes under which the Atlantic and Pacific Railroad Company received its grants of public land, to vest the lands absolutely in the company, without a right to the.Government to reacquire them on failure of the company to comply with the conditions of the grant; and no express provision for a forfeiture was necessary in order to fix the rights of 'the Government, and to …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"8","2":"29"}},{"t":"case","label":"Cravatt v. State","cite":"825 P.2d 277","y":1992,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/825/277/","by":{"1":"32","3":"8"}},{"t":"case","label":"Duro v. Reina","cite":"495 U.S. 676","y":1990,"id":"1989/88-6546","sc":1,"sum":"An Indian tribe may not assert criminal jurisdiction over a nonmember Indian.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2","2":"49, 50"}},{"t":"case","label":"Elk v. Wilkins","cite":"112 U.S. 94","y":1884,"id":"scdb/1884-014","sc":1,"sum":"An Indian, born a member of one of the Indian tribes within the United States, which.still exists and is recognized as a tribe by the government of the United States, who has voluntarily separated himself from his tribe, and taken up his residence among the white citizens of a State, but who has not been naturalized, or taxed, or recognized as a citizen, either by the United States or by the State, is not a citizen …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"McGlassen v. State","cite":"130 P. 1174","y":1913,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./130/1174/","by":{"1":"30","2":"47"}},{"t":"case","label":"Murphy v. Oklahoma","cite":"551 U.S. 1102","y":2007,"url":"https://supreme.justia.com/cases/federal/us/551/1102/","sc":1,"by":{"1":"3"}},{"t":"case","label":"Muscogee (Creek) Nation v. Hodel","cite":"851 F.2d 1439","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/851/1439/","by":{"1":"27, 31","2":"9","3":"4"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Nebraska v. Parker","cite":"136 S. Ct. 1072","y":2016,"id":"2015/14-1406","sc":1,"ar":4,"sum":"The Court determined that the passage of the 1882 Act by Congress did not diminish the original boundaries of the Omaha Indian Reservation.","sumSrc":"Oyez","by":{"1":"7, 17, 24","2":"passim","3":"15"}},{"t":"case","label":"Negonsott v. Samuels","cite":"507 U.S. 99","y":1993,"id":"1992/91-5397","sc":1,"sum":"Petitioner Negonsott, a member of the Kickapoo Tribe and a resident of the Kickapoo Reservation in Kansas, was convicted by a County District Court jury of aggravated battery for shooting another Indian on the reservation. The court set aside the conviction on the ground that the Federal Government had exclusive jurisdiction to prosecute Negonsott for the shooting under the Indian Major Crimes Act, 18 U. S. C. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2","2":"46, 49"}},{"t":"case","label":"Rosebud Sioux Tribe v. Kneip","cite":"430 U.S. 584","y":1977,"id":"1976/75-562","sc":1,"sum":"Both the language and legislative history of the Acts of 1904, 1907, and 1910, whereby land in certain counties in South Dakota located within the boundaries of the Rosebud Sioux Reservation as defined in an 1889 Treaty was required to be ceded by the Reservation Indians to the Government for sale to settlers under the homestead and townsite laws with the proceeds to be credited to the Indians only as received or, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 24","2":"24, 27-28, 37"}},{"t":"case","label":"State v. Brooks","cite":"763 P.2d 707","y":1988,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/763/707/","by":{"1":"32"}},{"t":"case","label":"Stewart v. Keyes","cite":"295 U.S. 403","y":1935,"id":"scdb/1934-127","sc":1,"by":{"1":"29"}},{"t":"case","label":"United States v. John","cite":"437 U.S. 634","y":1978,"id":"1977/77-836","sc":1,"sum":"Lands designated as a reservation for Choctaw Indians residing in central Mississippi held, on the basis of the history of the relations between the Mississippi Choctaws and the United States, to be \"Indian country,\" as defined in 18 U. S. C. § 1151 (1976 ed.) to include \"all land within the limits of any Indian reservation under the jurisdiction of the United States Government,\" and as used in the Major Crimes Act, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/18/1153","subs":["(a)"],"by":{"1":"2"}},{"t":"usc","label":"25 U.S.C. § 5101","url":"https://www.law.cornell.edu/uscode/text/25/5101","by":{"1":"20"}},{"t":"usc","label":"25 U.S.C. § 5201","url":"https://www.law.cornell.edu/uscode/text/25/5201","by":{"1":"20"}},{"t":"usc","label":"25 U.S.C. § 5203","url":"https://www.law.cornell.edu/uscode/text/25/5203","by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/18/1152","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 3598","url":"https://www.law.cornell.edu/uscode/text/18/3598","by":{"1":"3"}},{"t":"usc","label":"25 U.S.C. § 2020","url":"https://www.law.cornell.edu/uscode/text/25/2020","subs":["(d)(1)","(d)(2)"],"by":{"1":"21, 21"}},{"t":"usc","label":"25 U.S.C. § 2719","url":"https://www.law.cornell.edu/uscode/text/25/2719","subs":["(a)(2)(A)(i)"],"by":{"1":"21"}},{"t":"usc","label":"25 U.S.C. § 3103","url":"https://www.law.cornell.edu/uscode/text/25/3103","subs":["(12)"],"by":{"1":"21"}},{"t":"usc","label":"25 U.S.C. § 3202","url":"https://www.law.cornell.edu/uscode/text/25/3202","subs":["(9)"],"by":{"1":"21"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 5318","url":"https://www.law.cornell.edu/uscode/text/42/5318","subs":["(n)(2)"],"by":{"1":"21"}},{"t":"case","label":"Atkinson Trading Co. v. Shirley","cite":"532 U.S. 645","y":2001,"id":"2000/00-454","sc":1,"ar":1,"sum":"The Court held that the Navajo Nation's imposition of a hotel occupancy tax upon nonmembers on non-Indian fee land within its reservation is invalid.","sumSrc":"Oyez","by":{"2":"56","3":"5"}},{"t":"case","label":"Brendale v. Confederated Tribes & Bands of the Yakima Indian Nation","cite":"492 U.S. 408","y":1989,"id":"1988/87-1622","sc":1,"sum":"The treaty between the United States and the Yakima Indian Nation (Yakima Nation or Tribe) provided that the Tribe would retain its reservation for its \"exclusive use and benefit,\" and that \"no white man [shall] be permitted to reside upon the said reservation without [the Tribe's] permission.\" Much of the reservation is located in Yakima County, Washington. Roughly 80% of the reservation land is held in trust by …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"56"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Cass County v. Leech Lake Band of Chippewa Indians","cite":"524 U.S. 103","y":1998,"id":"1997/97-174","sc":1,"sum":"The Court held that ad valorem taxes may be imposed upon such land. \"When Congress makes Indian reservation land freely alienable, it manifests an unmistakably clear intent to render such land subject to state and local taxation,\" wrote Justice Thomas. Repurchasing the land by an Indian tribe does not return the land to tax-exempt status.","sumSrc":"Oyez","by":{"2":"54"}},{"t":"case","label":"City of Sherrill v. Oneida Indian Nation of New York","cite":"544 U.S. 197","y":2005,"id":"2004/03-855","sc":1,"ar":6,"sum":"The Court held that standards of federal Indian law and federal equity precluded the Tribe from unilaterally reviving its ancient sovereignty over the land at issue.","sumSrc":"Oyez","by":{"2":"56"}},{"t":"case","label":"Colliflower v. Garland","cite":"342 F.2d 369","y":1965,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/342/369/","by":{"2":"49"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"County of Yakima v. Confederated Tribes & Bands of Yakima Indian Nation","cite":"502 U.S. 251","y":1992,"id":"1991/90-408","sc":1,"sum":"The Indian General Allotment Act of 1887 permits Yakima County to impose an ad valorem tax on reservation land patented in fee pursuant to the Act and owned by reservation Indians or the Yakima Indian Nation itself, but does not allow the county to enforce its excise tax on sales of such land.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23, 54"}},{"t":"case","label":"Ellis v. Page","cite":"351 F.2d 250","y":1965,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/351/250/","by":{"2":"51"}},{"t":"case","label":"Enlow v. Bevenue","cite":"1994 WL 1048313","y":1994,"court":"Muscogee Creek Nat. Sup. Ct. Oct. 13","by":{"2":"16"}},{"t":"case","label":"Fitzgerald v. Barnstable School Committee","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"sum":"The Court found that a claim filed under Title IX for violation of the Equal Protection Clause of the fourteenth Amendment does not preclude the use of 42 U.S.C. Section 1983 which protects against the deprivation of any rights guaranteed by the Constitution and federal law.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Indian Country, U.S.A., Inc. v. Oklahoma ex rel. Oklahoma Tax Commission","cite":"829 F.2d 967","y":1987,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/829/967/","by":{"2":"17, 45, 48"}},{"t":"case","label":"Johnson v. Riddle","cite":"240 U.S. 467","y":1916,"id":"scdb/1915-122","sc":1,"sum":"Under the provisions relating to town sites, in the Atoka Agreement bfetween the United States and the Choctaw and Chickasaw tribes (found in Act of June 28, 1898, c. 517; 30 Stat. 495, 505, 508),-the preferential right to purchase improved town lots was conferred upon the owner of “permanent, substantial, and valuable improvements, other than fences) tillage, and temporary houses,” without regard' to.the lawfulness …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Lafferty v. State ex rel. Jameson","cite":"125 N.W.2d 171","y":1963,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W.2d/125/171/","by":{"2":"46"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"sum":"The Court decided that administrative law judges of the Securities and Exchange Commission are \"officers of the United States\" subject to the Constitution's Appointments Clause.","sumSrc":"Oyez","by":{"2":"58"}},{"t":"case","label":"Maxey v. Wright","cite":"54 S.W. 807","y":1900,"court":"Ct. App. Ind. Terr.","url":"https://www.courtlistener.com/c/S.W./54/807/","by":{"2":"29"}},{"t":"case","label":"Mertens v. Hewitt Associates","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Michigan v. Bay Mills Indian Community","cite":"134 S. Ct. 2024","y":2014,"id":"2013/12-515","sc":1,"op":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Minnesota v. Hitchcock","cite":"185 U.S. 373","y":1902,"id":"scdb/1901-038","sc":1,"sum":"The original jurisdiction, vested by the Constitution in this court over controversies in which a State is a party, is not affected by the question whether the State is a party plaintifE or party defendant.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"28-29"}},{"t":"case","label":"Minnesota v. Mille Lacs Band of Chippewa Indians","cite":"526 U.S. 172","y":1999,"id":"1998/97-1337","sc":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that the Mille Lacs Band of Chippewa Indians does have usufructuary rights that were guaranteed to them by the 1837 treaty.","sumSrc":"Oyez","by":{"2":"23, 37"}},{"t":"case","label":"Montana v. United States","cite":"450 U.S. 544","y":1981,"id":"1980/79-1128","sc":1,"op":1,"ar":1,"sum":"By a tribal regulation, the Crow Tribe of Montana sought to prohibit hunting and fishing within its reservation by anyone who is not a member of the Tribe. Relying on its purported ownership of the bed of the Big Horn River, on treaties which created its reservation, and on its inherent power as a sovereign, the Tribe claimed authority to prohibit hunting and fishing by nonmembers of the Tribe even on lands within …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"56"}},{"t":"case","label":"Morris v. Hitchcock","cite":"194 U.S. 384","y":1904,"id":"scdb/1903-115","sc":1,"sum":"The constitutionality of the Curtis Act, 30 Stat. 495, for the protection of the Indian Territory has been settled by this court and is not now open to question. Stephens v. Cherokee Nation, 174 U. S. 445; Cherokee Nation v. Hitchcock, 187 U. S. 294.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"10, 33","3":"5"}},{"t":"case","label":"Morris v. Hitchcock","cite":"21 App. D.C. 565","y":1903,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/App.%20D.C./21/565/","by":{"2":"10-11, 33"}},{"t":"case","label":"National Association of Manufacturers v. Department of Defense","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Nevada Department of Human Resources v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Puerto Rico v. Sanchez Valle","cite":"136 S. Ct. 1863","y":2016,"id":"2015/15-108","sc":1,"sum":"The Court held that Puerto Rico and the U.S. federal government are the same sovereign entity for the purpose of the Double Jeopardy Clause.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Raygor v. Regents of University of Minnesota","cite":"534 U.S. 533","y":2002,"id":"2001/00-1514","sc":1,"sum":"The Court held that the Board of Regents of the University of Minnesota never consented to suit in federal court on Raygor and Goodrich's state law claims and that the federal supplemental jurisdiction statute does not toll the period of limitations for state law claims asserted against nonconsenting state defendants that are dismissed on Eleventh Amendment grounds.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Southern Surety Co. v. Oklahoma","cite":"241 U.S. 582","y":1916,"id":"scdb/1915-155","sc":1,"sum":"By reason of the conditions arising out of the presence of the Five Civilized Tribes no organized territorial government was ever established in the Indian Territory; and, in the absence of an organized local government, prosecutions for crime were, regardless of their nature, commenced and prosecuted in the name of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Springer v. Townsend","cite":"222 F. Supp. 231","y":1963,"court":"N.D. Okla.","url":"https://www.courtlistener.com/c/F.%20Supp./222/231/","by":{"2":"53"}},{"t":"case","label":"State ex rel. Best v. Superior Court for Okanogan County","cite":"181 P. 688","y":1919,"court":"Wash.","url":"https://www.courtlistener.com/c/P./181/688/","by":{"2":"46"}},{"t":"case","label":"State ex rel. May v. Seneca-Cayuga Tribe of Oklahoma","cite":"711 P.2d 77","y":1985,"court":"Okla.","url":"https://www.courtlistener.com/c/P.2d/711/77/","by":{"2":"15"}},{"t":"case","label":"State ex rel. Miller v. Huser","cite":"184 P. 113","y":1919,"court":"Okla.","url":"https://www.courtlistener.com/c/P./184/113/","by":{"2":"53"}},{"t":"case","label":"State v. Barnes","cite":"137 N.W.2d 683","y":1965,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W.2d/137/683/","by":{"2":"46"}},{"t":"case","label":"State v. Sauter","cite":"205 N.W. 25","y":1925,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W./205/25/","by":{"2":"46"}},{"t":"case","label":"Tillett v. Lujan","cite":"931 F.2d 636","y":1991,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/931/636/","by":{"2":"49"}},{"t":"case","label":"United States v. Creek Nation","cite":"201 Ct. Cl. 386","y":1973,"url":"https://www.courtlistener.com/c/Ct.%20Cl./201/386/","by":{"2":"6-7"}},{"t":"case","label":"United States v. Goldfeder","cite":"112 F.2d 615","y":1940,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/112/615/","by":{"2":"53"}},{"t":"case","label":"United States v. La Plant","cite":"200 F. 92","y":1911,"court":"D.S.D.","url":"https://www.courtlistener.com/c/F./200/92/","by":{"2":"46"}},{"t":"case","label":"United States v. Ramsey","cite":"271 U.S. 467","y":1926,"id":"scdb/1925-135","sc":1,"by":{"2":"48"}},{"t":"case","label":"United States v. Wright","cite":"229 U.S. 226","y":1913,"id":"scdb/1912-230","sc":1,"sum":"In determining the effect of statutes regarding the introduction of liquor into Indian country, within the territorial limits of Oklahoma, every consideration arising out of the guardianship of the Federal Government over the Indians and control of their land indicate that as to them the liquor prohibition should be maintained after Statehood so far as consistent with the control of the State over its internal …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"52","3":"19"}},{"t":"case","label":"Washington v. Confederated Tribes of Colville Indian Reservation","cite":"447 U.S. 134","y":1980,"id":"1979/78-630","sc":1,"sum":"These cases concern challenges of several Indian Tribes to efforts by the State of Washington to apply various state taxes and other laws to transactions and activities occurring on Indian reservations. Washington imposes a cigarette excise tax on the \"sale, use, consumption, handling, possession or distribution\" of cigarettes within the State. It also imposes a general retail sales tax on sales of personal …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"56"}},{"t":"case","label":"White Mountain Apache Tribe v. Bracker","cite":"448 U.S. 136","y":1980,"id":"1979/78-1177","sc":1,"sum":"The Arizona taxes are pre-empted by federal law. Cf. Warren Trading Post Co. v. Arnzona Tax Comm'n, 380 U. S. 685.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"56"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"2":"59"}},{"t":"reg","label":"Law and Order on Indian Reservations, 44 Fed. Reg. 37,502","url":"https://www.govinfo.gov/link/fr/44/37502","by":{"2":"49"}},{"t":"case","label":"Choctaw Nation v. Oklahoma","cite":"397 U.S. 620","y":1970,"id":"1969/41","sc":1,"sum":"The Supreme Court held that the United States granted the Indian Nations rights to the riverbed of the Arkansas River where it was completely within the boundaries of the granted land and where it formed the border. Justice William O. Douglas concurred, writing that only the continuation of discrimination would justify denying the Indian Nations their claim.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Hanes v. State","cite":"973 P.2d 330","y":1998,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/973/330/","by":{"3":"8"}},{"t":"case","label":"Hous. Auth. of Seminole Nation v. Harjo","cite":"790 P.2d 1098","y":1990,"court":"Okla.","url":"https://www.courtlistener.com/c/P.2d/790/1098/","by":{"3":"8"}},{"t":"usc","label":"25 U.S.C. § 1911","url":"https://www.law.cornell.edu/uscode/text/25/1911","subs":["(a)"],"by":{"3":"21"}},{"t":"law","label":"Pub. L. No. 113-4","url":"https://www.govinfo.gov/link/plaw/113/public/4","by":{"3":"21"}}]};